def rule_text_span_contains_exact_name_annotation(doc: dict) -> list[dict]:
    """Match spans whose text_span contains the exact-name-of-registrant annotation and return the span itself."""
    try:
        texts = doc.get("texts", [])
        out = []
        for span in texts:
            ts = (span.get("text_span", "") or "").lower()
            if "exact name of registrant as specified in its charter" in ts:
                out.append(span)
        return out
    except Exception:
        return []

def rule_page1_company_name_from_exact_name_sibling_cluster(doc: dict) -> list[dict]:
    """Match spans in the same sibling cluster as the exact-name annotation, preferring the first bold/large one."""
    try:
        texts = doc.get("texts", [])
        out = []
        for child in texts:
            if child.get("page_no") != 1:
                continue
            if "exact name of registrant as specified in its charter" not in (child.get("text", "") or "").lower():
                continue
            pid = child.get("structure", {}).get("parent_id")
            if pid is not None and 0 <= pid < len(texts):
                out.append(texts[pid])
                continue
            # fallback: previous span
            idx = texts.index(child)
            if idx > 0:
                out.append(texts[idx - 1])
        return out
    except Exception:
        return []

def rule_cover_company_before_exact_name_line(doc: dict) -> list[dict]:
    """Match a company-like span immediately before the exact-name annotation line on page 1."""
    try:
        texts = doc.get("texts", [])
        out = []
        for i in range(len(texts) - 1):
            a = texts[i]
            b = texts[i + 1]
            if a.get("page_no") != 1 or b.get("page_no") != 1:
                continue
            if "exact name of registrant as specified in its charter" in (b.get("text", "") or "").lower():
                out.append(a)
        return out
    except Exception:
        return []

def rule_text_is_exact_name_annotation_parent(doc: dict) -> list[dict]:
    """Match parents of spans whose text is the exact-name-of-registrant annotation."""
    try:
        texts = doc.get("texts", [])
        out = []
        for child in texts:
            txt = (child.get("text", "") or "").strip().lower()
            if "exact name of registrant as specified in its charter" != txt.strip("()"):
                if "exact name of registrant as specified in its charter" not in txt:
                    continue
            pid = child.get("structure", {}).get("parent_id")
            if pid is not None and 0 <= pid < len(texts):
                out.append(texts[pid])
        return out
    except Exception:
        return []

